using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Automation;
using System.Windows.Media;
namespace TasiaCraft {
public partial class Editor {
 Grid homeOverlay;StackPanel homePage;
 string RecentFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TasiaCraft","recents.json");}}
 List<string> RecentPaths(){try{return json.Deserialize<List<string>>(File.ReadAllText(RecentFile)).Where(File.Exists).Distinct(StringComparer.OrdinalIgnoreCase).Take(12).ToList();}catch{return new List<string>();}}
 void RememberRecent(string path){try{var paths=RecentPaths();paths.RemoveAll(p=>string.Equals(p,path,StringComparison.OrdinalIgnoreCase));paths.Insert(0,path);Directory.CreateDirectory(Path.GetDirectoryName(RecentFile));File.WriteAllText(RecentFile,json.Serialize(paths.Take(12).ToArray()));}catch{}}
 void HideHome(){if(homeOverlay!=null)homeOverlay.Visibility=Visibility.Collapsed;}
 void ShowHome(){if(busy)return;Pause();var root=Content as Grid;if(root==null)return;if(homeOverlay==null){homeOverlay=new Grid{Background=B("#273139")};homeOverlay.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(208)});homeOverlay.ColumnDefinitions.Add(new ColumnDefinition());Grid.SetRowSpan(homeOverlay,6);root.Children.Add(homeOverlay);var nav=new StackPanel{Background=B("#20292f"),Margin=new Thickness(0)};nav.Children.Add(Text("TasiaCraft",24,accent));foreach(var label in new[]{"Home","Learn","Support","What's New"}){string page=label;var button=Btn(label,()=>HomePage(page));button.Margin=new Thickness(12,5,12,5);button.Padding=new Thickness(20,13,10,13);button.HorizontalContentAlignment=HorizontalAlignment.Left;AutomationProperties.SetAutomationId(button,"HomeNav."+label);nav.Children.Add(button);}homeOverlay.Children.Add(nav);homePage=new StackPanel{Margin=new Thickness(30,18,30,18)};var scroll=new ScrollViewer{Content=homePage,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetColumn(scroll,1);homeOverlay.Children.Add(scroll);}homeOverlay.Visibility=Visibility.Visible;HomePage("Home");}
 Button HomeCard(string glyph,string label,string id,Action action){var content=new StackPanel{Margin=new Thickness(8)};content.Children.Add(new TextBlock{Text=glyph,FontSize=42,Foreground=Brushes.White,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(5)});content.Children.Add(new TextBlock{Text=label,FontSize=13,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(5)});var button=Btn(label,action);button.Content=content;button.Background=B("#182227");button.Margin=new Thickness(7);button.MinHeight=116;AutomationProperties.SetName(button,label);AutomationProperties.SetAutomationId(button,id);return button;}
 void HomePage(string page){homePage.Children.Clear();if(page=="Home"){
  homePage.Children.Add(Text("Welcome to TasiaCraft!",30));
  homePage.Children.Add(new Border{Height=2,Background=B("#45535a"),Margin=new Thickness(8,8,8,22)});
  var cards=new UniformGrid{Columns=4};cards.Children.Add(HomeCard("▱","New Project","Home.NewProject",New));cards.Children.Add(HomeCard("▤","New From Template","Home.Template",ChooseTemplate));cards.Children.Add(HomeCard("▰","Open Project","Home.OpenProject",Open));cards.Children.Add(HomeCard("●","New Recording","Home.Record",()=>{New();if(homeOverlay.Visibility==Visibility.Collapsed)Record();}));homePage.Children.Add(cards);
  var recent=new StackPanel{Background=B("#303b43"),Margin=new Thickness(8,20,8,12),MinHeight=235};recent.Children.Add(Text("Recent Projects",19));recent.Children.Add(new Border{Height=1,Background=accent,Margin=new Thickness(8,0,8,10)});var paths=RecentPaths();if(paths.Count==0){recent.Children.Add(Text("No recent projects found",14,muted));recent.Children.Add(Btn("Quick Start Guide",()=>HomePage("Learn"),true));}else foreach(string path in paths){string p=path;var button=Btn(Path.GetFileNameWithoutExtension(p),()=>{if(!Discard())return;LoadProject(p);});button.Background=B("#263138");button.HorizontalContentAlignment=HorizontalAlignment.Left;button.ToolTip=p;recent.Children.Add(button);}homePage.Children.Add(recent);
  homePage.Children.Add(Text("Original Assets",19));homePage.Children.Add(Text("Create titles, shapes and backgrounds from the Library.",12,muted));homePage.Children.Add(Btn("Explore Library",()=>{New();if(homeOverlay.Visibility==Visibility.Collapsed){Panel("Library");HighlightNavigation();}},true));
 }else if(page=="Learn"){
  homePage.Children.Add(Text("Learn TasiaCraft",28));homePage.Children.Add(Text("1. Import media and place it on a timeline track.\n\n2. Select a canvas object. Drag it to move; resize with its corner handles; rotate with the circular arm. Properties update immediately.\n\n3. Drag timeline edges to trim, press S to split, and use Ctrl+Z to undo.\n\n4. Play or scrub the live timeline. View zoom changes the workspace without changing export dimensions.\n\n5. Save your project and export an MP4 video.",15));homePage.Children.Add(Btn("Start a Project",New,true));
 }else if(page=="Support"){
  homePage.Children.Add(Text("Support",28));homePage.Children.Add(Text("TasiaCraft is an independent Windows editor. Your projects reference source media by path; keep media files available or use Relink in the Media Bin.\n\nRecording devices can be listed in the Record dialog. Effects prepare source previews asynchronously; the status bar reports their state.\n\nThe delivery report lists tested workflows and known limitations.",15));homePage.Children.Add(Btn("Open local logs",()=>{string dir=Path.GetDirectoryName(RecentFile);Directory.CreateDirectory(dir);System.Diagnostics.Process.Start("explorer.exe",dir);}));homePage.Children.Add(Btn("Read delivery report",()=>{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"docs","FINAL-REPORT.md");if(File.Exists(path))System.Diagnostics.Process.Start("notepad.exe",path);}));
 }else{
  homePage.Children.Add(Text("What's New in TasiaCraft 0.2",28));homePage.Children.Add(Text("• Live multitrack preview without a whole-timeline render\n\n• Direct canvas movement, anchored resizing and rotation\n\n• Native media size and independent canvas view zoom\n\n• Compact Properties, original preset tiles and local Library\n\n• Track visibility, lock and snapping controls",16));homePage.Children.Add(Btn("Start Editing",()=>{HideHome();Refresh();},true));
 }}
 void ChooseTemplate(){var w=new Window{Title="TasiaCraft Templates",Owner=this,Width=440,Height=340,Background=panel,Foreground=Brushes.White,WindowStartupLocation=WindowStartupLocation.CenterOwner};var content=new StackPanel{Margin=new Thickness(18)};content.Children.Add(Text("Empty Canvas Templates",22));content.Children.Add(Text("Choose canvas dimensions. Add your own media and titles.",12,muted));string[] labels={"Blank 1080p  •  1920 × 1080","Blank 720p  •  1280 × 720","Blank Square  •  1080 × 1080"};int[] widths={1920,1280,1080},heights={1080,720,1080};for(int i=0;i<labels.Length;i++){int index=i;content.Children.Add(Btn(labels[i],()=>{w.Close();New();if(homeOverlay.Visibility==Visibility.Collapsed){project.Width=widths[index];project.Height=heights[index];projectConfigured=true;Refresh();}},true));}w.Content=content;w.ShowDialog();}
}
}
